import styled from "styled-components";

import { MCPIcon, ToolIcon } from "@src/icons";
import KnowledgeBaseIcon from "../../../../icons/KnowledgeBaseIcon";
import { KnowledgeBaseSpan, MCPSpan, Span } from "../../../../types/playground";
import { getDurationString } from "../../../../utils/timeUtils";
import Accordion from "../../../components/Accordion";
import { DivFlexRow } from "../../../components/elements/formelements";

const isKnowledgeBaseTool = (tool: Span): tool is KnowledgeBaseSpan => "kbDisplayName" in tool;
const isMCPTool = (tool: Span): tool is MCPSpan => "serverName" in tool;

interface ReferencesAndToolsProps {
    tools: Span[];
}

const ToolDuration = styled.span`
    font-size: 10px;
    color: ${({ theme }) => theme.colorsTextSecondaryDefault};
`;

const IconContainer = styled.div`
    font-size: 16px;
`;

const ReferencesAndTools: React.FC<ReferencesAndToolsProps> = ({ tools }) => {
    const renderTool = (tool: Span) => {
        let title, icon;
        if (isKnowledgeBaseTool(tool)) {
            icon = <KnowledgeBaseIcon />;
            title = tool.displayName;
        } else if (isMCPTool(tool)) {
            icon = <MCPIcon />;
            title = tool.toolName;
        } else {
            icon = <ToolIcon />;
            title = tool.displayName;
        }

        return (
            <DivFlexRow key={tool.spanId} marginTop={8} alignItems="center">
                <IconContainer>{icon}</IconContainer>
                <div>
                    <div>{title}</div>
                    <ToolDuration>{getDurationString(tool.durationMilliseconds)}</ToolDuration>
                </div>
            </DivFlexRow>
        );
    };

    return (
        <DivFlexRow marginTop={8}>
            <Accordion title="References & tools">{tools.map((tool) => renderTool(tool))}</Accordion>
        </DivFlexRow>
    );
};

export default ReferencesAndTools;
