import React, { ReactElement } from "react";
import { Button, ButtonProps } from "@mendix/ide-ui-components/button/Button";
import { Icon } from "@mendix/ide-ui-components/icon/Icon";
import styled from "styled-components";

const ButtonContent = styled.span`
    display: flex;
    align-items: center;
    gap: 4px;
`;

interface ButtonWithIconProps extends ButtonProps {
    label: string;
    icon: ReactElement | string;
    iconPosition?: "start" | "end";
    alt: string;
}

/**
 * ButtonWithIcon component for rendering a button with an icon.
 *
 * @param label - The text label for the button
 * @param icon - The icon to display, either as a React element or a base64 string
 * @param onPress - The function to call when the button is pressed
 * @param iconPosition - The position of the icon, either "start" or "end" (default: "start")
 * @param variant - The variant of the button (e.g., "primary", "secondary")
 * @param isDisabled - Whether the button is disabled
 * @param alt - The alt text for the icon image
 */
const ButtonWithIcon: React.FC<ButtonWithIconProps> = ({
    label,
    icon,
    onPress,
    iconPosition = "start",
    variant,
    isDisabled,
    alt,
}) => {
    const iconElement = typeof icon === "string" ? <Icon src={icon} alt={alt} /> : icon;

    return (
        <Button variant={variant} onPress={onPress} isDisabled={isDisabled}>
            <ButtonContent>
                {iconPosition === "start" && iconElement}
                {label}
                {iconPosition === "end" && iconElement}
            </ButtonContent>
        </Button>
    );
};

export default ButtonWithIcon;
