import { useEffect, useState } from "react";

import { Dropdown } from "@mendix/ide-ui-components/dropdown/dropdown/Dropdown";
import { DropdownListBoxItem } from "@mendix/ide-ui-components/dropdown/dropdown/DropdownListBox";
import { styled } from "styled-components/";

import { PlayIcon } from "@src/icons";
import { MOCK_TEST_CASES } from "../../../tests/fixtures/agent";
import { TestCase, TestVariable, Variable, UsageType } from "../../types/agent";
import { UsageTypes } from "@src/constants/agent";
import { Response } from "@src/types/playground";
import { ErrorBanner } from "../components/Banner";
import ButtonWithIcon from "../components/ButtonWithIcon";
import GroupBox from "../components/GroupBox";
import { HighlightRule } from "../components/TextAreaLabeled";
import { DivFlexRow } from "../components/elements/formelements";
import { BoldText } from "../components/elements/text";
import { ChatPlayground } from "./output/chat/ChatPlayground";
import { TaskPlayground } from "./output/task/TaskPlayground";
import { ErrorWithLink } from "@src/types/generic";

import { Message } from "@src/constants/chatPlayground";

const StyledDropdown = styled(Dropdown)`
    flex: 1;
`;

const ChatGroupBox = styled(GroupBox)`
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    overflow: hidden;
    max-height: calc(100vh - 30px);

    > div {
        display: flex;
        flex-direction: column;
        flex: 1;
        min-height: 0;
        overflow: hidden;
    }
`;

interface PlaygroundProps {
    variables: Variable[];
    highlightRules: HighlightRule[];
    isDisabled: boolean;
    showUnsavedChangesWarning: boolean;
    executeAction: (testVariables: TestVariable[], messages?: Message[]) => void;
    usageType: UsageType;
    isLoading?: boolean;
    response?: Response;
    agentName: string;
    isError?: boolean;
    error?: ErrorWithLink;
}

const Playground: React.FC<PlaygroundProps> = ({
    variables,
    highlightRules,
    isDisabled,
    showUnsavedChangesWarning,
    executeAction,
    usageType,
    isLoading = false,
    response,
    agentName,
    isError = false,
    error,
}) => {
    // TODO: replace mock data with actual test case data when the latter is implemented
    const [selectedTestCase, __setSelectedTestCase] = useState<TestCase>(MOCK_TEST_CASES[0]);

    // TODO; Initialize test variables based on variables prop and selected test case
    const [testVariables, setTestVariables] = useState<TestVariable[]>(
        variables.map((v) => ({
            ...v,
            value: "",
        }))
    );

    // Chat messages state
    const [messages, setMessages] = useState<Message[]>([]);

    // Clear messages when switching between task and chat usage types
    useEffect(() => {
        setMessages([]);
    }, [usageType]);

    // Add agent response to messages when available (for chat agents only)
    useEffect(() => {
        if (response && usageType === UsageTypes.Chat && !isLoading) {
            setMessages((prev) => {
                // Avoid adding duplicate responses
                const lastMessage = prev[prev.length - 1];
                if (lastMessage?.type === "agent") {
                    return prev;
                }

                const agentMessage: Message = {
                    type: "agent",
                    response: response,
                };
                return [...prev, agentMessage];
            });
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [response, isLoading]);

    // Sync testVariables when variables prop changes
    // TODO: sync testVariables when selectedTestCase changes
    useEffect(() => {
        setTestVariables((currentTestVariables) => {
            // Create a map of current test variables for quick lookup
            const currentMap = new Map(currentTestVariables.map((tv) => [tv.key, tv.value]));

            // Create new test variables array based on incoming variables
            return variables.map((v) => {
                // If variable already existed, keep its current value
                if (currentMap.has(v.key)) {
                    return { ...v, value: currentMap.get(v.key)! };
                }
                // New variable: use test case value or empty string
                return {
                    ...v,
                    value: "",
                };
            });
        });
    }, [variables]);

    const handleTestClick = () => executeAction(testVariables);

    const handleChatSubmit = (userPrompt: string) => {
        const newMessage: Message = {
            type: "user",
            text: userPrompt,
            timestamp: Date.now(),
        };

        const updatedMessages = [...messages, newMessage];
        setMessages(updatedMessages);
        executeAction(testVariables, updatedMessages);
    };

    const onVariableChange = (index: number, value: string) => {
        setTestVariables((currentTestVariables) => {
            const updatedVariables = [...currentTestVariables];
            updatedVariables[index] = { ...updatedVariables[index], value };
            return updatedVariables;
        });
    };

    const handleNewChat = () => {
        setMessages([]);
    };

    const PlaygroundGroupBox = usageType === UsageTypes.Chat ? ChatGroupBox : GroupBox;

    const renderChatInterface = () => {
        if (usageType !== UsageTypes.Chat) {
            return null;
        }

        return (
            <ChatPlayground
                agentName={agentName}
                isLoading={isLoading}
                isDisabled={isDisabled}
                onChatSubmit={handleChatSubmit}
                testVariables={testVariables}
                onVariableChange={onVariableChange}
                highlightRules={highlightRules}
                messages={messages}
                isError={isError}
                error={error}
            />
        );
    };

    const renderTaskInterface = () => {
        if (usageType !== UsageTypes.Task) {
            return null;
        }

        return (
            <TaskPlayground
                testVariables={testVariables}
                onVariableChange={onVariableChange}
                highlightRules={highlightRules}
            />
        );
    };

    return (
        <PlaygroundGroupBox label="Playground">
            {showUnsavedChangesWarning && (
                <ErrorBanner>
                    <BoldText>Unsaved agent changes detected</BoldText>
                    <div>To test your agent, restart the application to apply the latest changes.</div>
                </ErrorBanner>
            )}
            <DivFlexRow>
                <StyledDropdown
                    // TODO: check if below defaultValue prop issue is resolved in latest version of @mendix/ide-ui-components and remove the ts-ignore comment (SAS-1814)
                    // @ts-ignore
                    defaultValue={selectedTestCase?.uuid}
                    label="Test variable input"
                    aria-label="Test variable input"
                    isDisabled
                >
                    {MOCK_TEST_CASES.map((testCase) => (
                        <DropdownListBoxItem key={testCase.uuid} id={testCase.uuid}>
                            {testCase.name}
                        </DropdownListBoxItem>
                    ))}
                </StyledDropdown>
                <ButtonWithIcon
                    label={usageType === UsageTypes.Chat ? "New chat" : "Test"}
                    icon={usageType === UsageTypes.Chat ? <></> : <PlayIcon />}
                    onPress={usageType === UsageTypes.Chat ? handleNewChat : handleTestClick}
                    variant="primary"
                    isDisabled={isDisabled}
                    alt={usageType === UsageTypes.Chat ? "New chat icon" : "Run test icon"}
                />
            </DivFlexRow>
            {usageType === UsageTypes.Task && renderTaskInterface()}
            {usageType === UsageTypes.Chat && renderChatInterface()}
        </PlaygroundGroupBox>
    );
};

export default Playground;
