import { useEffect, useRef, useState, Fragment } from "react";
import styled from "styled-components";

import { TestVariable } from "@src/types/agent";
import { Message } from "@src/constants/chatPlayground";
import { ChatBox } from "@src/ui/agent/output/chat/ChatBox";
import Header from "@src/ui/agent/output/common/Header";
import Metadata from "@src/ui/agent/output/common/Metadata";
import ReferencesAndTools from "@src/ui/agent/output/common/ReferencesAndTools";
import MarkdownRenderer from "@src/ui/components/MarkdownRenderer";
import LoadingDots from "@src/ui/components/LoadingDots";
import VariablesList from "@src/ui/components/VariablesList";
import { HighlightRule } from "@src/ui/components/TextAreaLabeled";
import { copyToClipboard } from "@src/utils/clipboardUtils";
import { WarningBanner } from "@src/ui/components/Banner";
import { BoldText } from "@src/ui/components/elements/text";
import { Link } from "@mendix/ide-ui-components/link/Link";
import { ErrorWithLink } from "@src/types/generic";

const ChatContainer = styled.div`
    display: flex;
    flex-direction: column;
    height: round(calc(100% - 1px), 2px);
    min-height: 0;
    overflow: hidden;
`;

const VariablesWrapper = styled.div`
    flex-shrink: 0;
    margin-bottom: 8px;
`;

const MessagesContainer = styled.div`
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 8px 8px;
`;

const MessageWrapper = styled.div`
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 12px 0;
    flex-shrink: 0;
`;

const UserMessageWrapper = styled.div`
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 12px 0;
    flex-shrink: 0;
`;

const MessageDivider = styled.div`
    width: 100%;
    height: 1px;
    background-color: ${({ theme }) => theme.colorsBorderPrimary};
    margin: 4px 0;
    flex-shrink: 0;
`;

const ChatBoxWrapper = styled.div`
    flex-shrink: 0;
    margin-top: 12px;
`;

interface ChatPlaygroundProps {
    agentName: string;
    isLoading: boolean;
    isDisabled: boolean;
    onChatSubmit: (question: string) => void;
    testVariables: TestVariable[];
    onVariableChange: (index: number, value: string) => void;
    highlightRules: HighlightRule[];
    messages?: Message[];
    isError?: boolean;
    error?: ErrorWithLink;
}

export const ChatPlayground: React.FC<ChatPlaygroundProps> = ({
    agentName,
    isLoading,
    isDisabled,
    onChatSubmit,
    testVariables,
    onVariableChange,
    highlightRules,
    messages = [],
    isError = false,
    error,
}) => {
    const [userPrompt, setUserPrompt] = useState("");
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const messagesContainerRef = useRef<HTMLDivElement>(null);

    // Auto-scroll to bottom when messages change
    useEffect(() => {
        if (messagesContainerRef.current) {
            messagesContainerRef.current.scrollTop = messagesContainerRef.current.scrollHeight;
        }
    }, [messages, isLoading]);

    const handleChatSubmit = () => {
        if (userPrompt.trim()) {
            onChatSubmit(userPrompt);
            setUserPrompt("");
        }
    };

    const renderMessages = () => (
        <MessagesContainer ref={messagesContainerRef}>
            {messages.map((msg, index) => {
                const isLastMessage = index === messages.length - 1;
                const messageKey = msg.type === "user" ? `user-${msg.timestamp}` : `agent-${msg.response.receivedAt}`;

                if (msg.type === "user") {
                    return (
                        <Fragment key={messageKey}>
                            <UserMessageWrapper>
                                <Header name="You" timestamp={msg.timestamp} />
                                <MarkdownRenderer content={msg.text} />
                            </UserMessageWrapper>
                            {!isLastMessage && <MessageDivider />}
                        </Fragment>
                    );
                }

                return (
                    <Fragment key={messageKey}>
                        <MessageWrapper>
                            <Header name={agentName} timestamp={msg.response.receivedAt} />
                            <MarkdownRenderer content={msg.response.responseText} />
                            <Metadata
                                totalTokens={msg.response.totalTokens}
                                requestTokens={msg.response.requestTokens}
                                responseTokens={msg.response.responseTokens}
                                duration={msg.response.durationMilliseconds}
                                handleCopyClick={() => copyToClipboard(msg.response.responseText)}
                            />
                            {msg.response.tools && msg.response.tools.length > 0 && (
                                <ReferencesAndTools tools={msg.response.tools} />
                            )}
                        </MessageWrapper>
                        {!isLastMessage && <MessageDivider />}
                    </Fragment>
                );
            })}
            {isError && error && (
                <>
                    {messages.length > 0 && <MessageDivider />}
                    <MessageWrapper>
                        <WarningBanner>
                            <BoldText>Test execution failed</BoldText>
                            <div>{error.message}</div>
                            {error.link && (
                                <div>
                                    For more information, please visit{" "}
                                    <Link href={error.link} target="_blank" rel="noopener noreferrer">
                                        MxDocs
                                    </Link>
                                    .
                                </div>
                            )}
                        </WarningBanner>
                    </MessageWrapper>
                </>
            )}
            {isLoading && (
                <>
                    {messages.length > 0 && <MessageDivider />}
                    <MessageWrapper>
                        <LoadingDots />
                    </MessageWrapper>
                </>
            )}
            <div ref={messagesEndRef} />
        </MessagesContainer>
    );

    return (
        <ChatContainer>
            <VariablesWrapper>
                {testVariables.length > 0 && (
                    <VariablesList
                        variables={testVariables}
                        highlightRules={highlightRules}
                        onVariableChange={onVariableChange}
                    />
                )}
            </VariablesWrapper>

            {renderMessages()}
            <ChatBoxWrapper>
                <ChatBox
                    disabled={isDisabled || isLoading}
                    onSubmit={handleChatSubmit}
                    userPrompt={userPrompt}
                    updateUserPrompt={setUserPrompt}
                    isLoading={isLoading}
                />
            </ChatBoxWrapper>
        </ChatContainer>
    );
};
