import { DesignSystemTokens } from "@mendix/ide-theming";
import { BaseTextArea } from "@mendix/ide-ui-components/input/TextArea";
import { ChangeEvent, FC, KeyboardEventHandler, PropsWithChildren, useCallback } from "react";
import styled from "styled-components";

type ChatBoxTextAreaProps = PropsWithChildren<{
    onSubmit: () => Promise<void> | void;
    disabled: boolean;
    value: string;
    updateValue: (value: string) => void;
    id?: string;
    isLoading: boolean;
}>;

export const ChatBoxTextArea: FC<ChatBoxTextAreaProps> = ({
    onSubmit,
    disabled,
    value,
    updateValue,
    children,
    id = "AgentEditorChatInput",
    isLoading,
}) => {
    const handleKeyDown = useCallback<KeyboardEventHandler<HTMLTextAreaElement>>(
        async (e) => {
            // Make sure `Shift + Enter` will add a line-break, otherwise `Enter` will send the question
            if (e.key === "Enter") {
                if (e.shiftKey) return;

                // Make sure onChange event doesn't get triggered
                e.preventDefault();
                await onSubmit();
            }
        },
        [onSubmit]
    );

    const onChange = useCallback(
        (e: ChangeEvent<HTMLTextAreaElement>) => {
            updateValue(e.currentTarget.value);
            // Update textarea height
            e.currentTarget.style.height = "0px"; // Reset to 0 so that textarea can also get smaller again
            e.currentTarget.style.height = e.currentTarget.scrollHeight + 2 + "px";
        },
        [updateValue]
    );

    return (
        <ChatBoxForm>
            <StyledTextArea
                id={id}
                value={value}
                required
                onKeyDown={handleKeyDown}
                onChange={onChange}
                placeholder={
                    disabled && !isLoading
                        ? "Save your changes and run the app to enable chat"
                        : "What can I help you with?"
                }
                disabled={disabled || isLoading}
                tabIndex={1}
                title="" // setting title to an empty string removes the default tooltip "Please fill out this field."
                onDragOver={(e) => e.preventDefault()} // prevent cursor changing to (+)
                onDrop={(e) => e.preventDefault()} // block dropping a file
            />
            <ChatBoxBottomPart>{children}</ChatBoxBottomPart>
        </ChatBoxForm>
    );
};

const StyledTextArea = styled(BaseTextArea)`
    min-height: 58px;
    max-height: 106px;
    padding: ${DesignSystemTokens.spacing8};
`;

const ChatBoxBottomPart = styled.div`
    border: ${DesignSystemTokens.borderWidthMd} solid ${({ theme }) => theme.colorsBorderInputDefault};
    border-top: 0;
    padding: ${DesignSystemTokens.spacing4} ${DesignSystemTokens.spacing8} ${DesignSystemTokens.spacing8};
    border-radius: 0 0 ${DesignSystemTokens.borderRadiusXs} ${DesignSystemTokens.borderRadiusXs};
    margin-top: ${DesignSystemTokens.spacing0};
    background-color: transparent;
`;

const ChatBoxForm = styled.form`
    display: flex;
    flex-direction: column;
    align-items: stretch;
    background-color: ${({ theme }) => theme.colorsBackgroundInputBase};
    border-radius: ${DesignSystemTokens.borderRadiusXs};

    textarea {
        background-color: transparent;
        border-bottom: 0;
        border-radius: ${DesignSystemTokens.borderRadiusXs} ${DesignSystemTokens.borderRadiusXs} 0 0;

        // Make sure the fake inside area (where the buttons are) of the textarea gets the same hover/active styling
        &:hover:enabled + ${ChatBoxBottomPart} {
            border-color: ${({ theme }) => theme.colorsBorderInputHover};
        }

        &:active:enabled + ${ChatBoxBottomPart}, &:focus:enabled + ${ChatBoxBottomPart} {
            border-color: ${({ theme }) => theme.colorsBorderActive};
        }

        // Make sure the form background changes when disabled
        &:disabled {
            background-color: transparent;
        }
    }

    &:has(textarea:disabled) {
        background-color: ${({ theme }) => theme.colorsBackgroundDefault};
        opacity: 0.6;
    }
`;
