import { DesignSystemTokens } from "@mendix/ide-theming";
import { ComponentProps, FC } from "react";
import styled from "styled-components";
import { ChatBoxTextArea } from "./ChatBoxTextArea";
import { IconButton } from "@mendix/ide-ui-components/button/IconButton";
import { SendIcon } from "@src/icons";

export interface ChatBoxProps {
    disabled: boolean;
    onSubmit: ComponentProps<typeof ChatBoxTextArea>["onSubmit"];
    userPrompt: string;
    updateUserPrompt: (value: string) => void;
    isLoading: boolean;
}

export const ChatBox: FC<ChatBoxProps> = ({ onSubmit, disabled, userPrompt, updateUserPrompt, isLoading }) => {
    return (
        <ChatBoxWrapper>
            <ChatBoxTextArea
                onSubmit={onSubmit}
                disabled={disabled}
                value={userPrompt}
                updateValue={updateUserPrompt}
                isLoading={isLoading}
            >
                <ChatBoxContentContainer>
                    <PrimaryIconButton
                        icon={<SendIcon />}
                        aria-label="Send message"
                        isDisabled={userPrompt.trim() === "" || disabled || isLoading}
                        onPress={onSubmit}
                    />
                </ChatBoxContentContainer>
            </ChatBoxTextArea>
        </ChatBoxWrapper>
    );
};

export const ChatBoxWrapper = styled.section`
    flex-basis: 80px;
`;

export const ChatBoxContentContainer = styled.div`
    display: flex;
    justify-content: flex-end;
    gap: ${DesignSystemTokens.spacing4};
    align-items: center;
`;

const PrimaryIconButton = styled(IconButton)`
    background-color: ${({ theme }) => theme.colorsBackgroundButtonPrimaryButtonDefault};
    color: ${({ theme }) => theme.colorsAccentWhite};
    border-radius: 4px;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;

    &:hover:not(:disabled) {
        background-color: ${({ theme }) => theme.colorsBackgroundButtonPrimaryButtonHover};
    }

    &:active:not(:disabled) {
        background-color: ${({ theme }) => theme.colorsBackgroundButtonPrimaryButtonHover};
    }

    &:disabled {
        opacity: 0.5;
    }
`;
