import { Key } from "react";

import { ComboBox } from "@mendix/ide-ui-components/dropdown/combobox/ComboBox";
import { DropdownListBoxItem } from "@mendix/ide-ui-components/dropdown/dropdown/DropdownListBox";
import { ToolChoices, ToolTypes } from "@src/constants/tool";
import { ToolChoice } from "@src/types/tool";
import { Agent } from "@src/types/agent";
import { ValidationInfo } from "./agentEditor";
import { Link } from "@mendix/ide-ui-components/link/Link";

const toolChoiceOptions: { key: ToolChoice; caption: string }[] = [
    { key: ToolChoices.Auto, caption: "Auto" },
    { key: ToolChoices.None, caption: "None" },
    { key: ToolChoices.Any, caption: "Any" },
    { key: ToolChoices.Tool, caption: "Tool" },
];

interface ToolChoiceProps {
    agent: Agent;
    validationInfo: ValidationInfo;
    onToolChoiceChange: (key: Key | null) => void;
    onToolChoiceToolChange: (toolName: Key | null) => void;
}

const ToolChoiceSelection: React.FC<ToolChoiceProps> = ({
    agent,
    validationInfo,
    onToolChoiceChange,
    onToolChoiceToolChange,
}) => {
    return (
        <>
            <ComboBox
                aria-label="Tool choice"
                label="Tool choice"
                selectedKey={agent.toolChoice ?? null}
                validate={undefined}
                onSelectionChange={onToolChoiceChange}
                description={
                    <>
                        Control the behavior of the agent regarding tools used.{" "}
                        <Link
                            href="https://docs.mendix.com/appstore/modules/genai/genai-for-mx/commons/#enum-toolchoice"
                            target="_blank"
                            rel="noreferrer,noopener"
                        >
                            Read more.
                        </Link>
                    </>
                }
            >
                {toolChoiceOptions.map((option) => (
                    <DropdownListBoxItem key={option.key} id={option.key}>
                        {option.caption}
                    </DropdownListBoxItem>
                ))}
            </ComboBox>
            {agent.toolChoice === ToolChoices.Tool && (
                <ComboBox
                    aria-label="Tool choice tool"
                    label="Tool"
                    selectedKey={agent.toolChoiceToolName ?? null}
                    validate={() => validationInfo.isValidToolChoice}
                    onSelectionChange={onToolChoiceToolChange}
                    description="Only microflows can be selected as tool choice."
                >
                    {agent.tools
                        .filter((tool) => tool.toolType === ToolTypes.Microflow)
                        .map((tool) => (
                            <DropdownListBoxItem key={tool.name} id={tool.name}>
                                {tool.name}
                            </DropdownListBoxItem>
                        ))}
                </ComboBox>
            )}
        </>
    );
};

export default ToolChoiceSelection;
